import argparse,gzip,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True);p.add_argument('--start-index',type=int,default=0);args=p.parse_args()
ref=json.loads(gzip.decompress(Path('docs/heuristic-matrix-reference.json.gz').read_bytes()));exe=Path('build/petri-comparison-checkpoint-build/Release/minera_export.exe');before=hashlib.sha256(exe.read_bytes()).hexdigest();checks=[]
flags={'dependency_thresh':'--dependency-threshold','and_measure_thresh':'--and-threshold','min_act_count':'--heuristic-min-activity-count','min_dfg_occurrences':'--min-edge-frequency','dfg_pre_cleaning_noise_thresh':'--heuristic-dfg-pre-cleaning-noise-threshold','loop_length_two_thresh':'--heuristic-loop-length-two-threshold'}
for i,r in enumerate(ref['observations'][args.start_index:],start=args.start_index):
 x=Path(f'build/heuristic-matrix-{i}.xes');x.write_text(r['xes']);out=x.with_suffix('.json')
 cmd=[str(exe),str(x),'--heuristic-variant',r['variant'].lower(),'--heuristic-decoration',r['decoration'],'--heuristic-performance-aggregation',r['aggregation'],'-o',str(out)]
 if 'pm4py:param:start_timestamp_key' in r['parameters']: cmd+=['--heuristic-start-timestamp-attribute',r['parameters']['pm4py:param:start_timestamp_key']]
 for key,flag in flags.items():
  if key in r['parameters']: cmd += [flag,str(r['parameters'][key])]
 row={'name':r['name'],'expected':r.get('expected'),'expected_error':r.get('expected_error')}
 try:
  proc=subprocess.run(cmd,capture_output=True,text=True,timeout=30);row.update(exit_code=proc.returncode,stderr=proc.stderr)
  if proc.returncode==0:
   payload=json.loads(out.read_text());net=payload['heuristics_net'];names=net['activities'] if net['activity_ids_are_local'] else [a['name'] for a in payload['activities']]
   edges=[[names[e['source']],names[e['target']],e['dependency'],e['frequency'],e['representation']] for e in net['edges']]
   actual={'active':sorted(names[i] for i in net['active_activities']),'edges':sorted(edges,key=lambda e:json.dumps(e,sort_keys=True))}
   for key,value in [('dependency_measures','value'),('loop_length_two','frequency')]:
    actual[key]=sorted([[names[s['source']],names[s['target']],s[value]] for s in net[key]]) if key in net else None
   row['actual']=actual
   row['unchanged']={k:net[k] for k in ['input_bundles','output_bundles','and_measures_in','and_measures_out']}
  row['matched']=proc.returncode!=0 if 'expected_error' in r else row.get('actual')==r['expected']
 except subprocess.TimeoutExpired: row.update(timeout=True,matched=False)
 checks.append(row)
 if (i+1)%108==0: print(i+1,'checked',flush=True)
after=hashlib.sha256(exe.read_bytes()).hexdigest();assert before==after
Path(args.output).write_text(json.dumps({'checks':checks,'native_executable_sha256':after},indent=2)+'\n',encoding='utf-8')
print(sum(r['matched'] for r in checks),'/',len(checks));print([r['name'] for r in checks if not r['matched']][:25])
